function validate([root]) {
  if (!Array.isArray(root)) return 'root is a level-order array with null for missing children.';
  if (root.length > 0 && root[0] === null) return 'An empty tree is written as [].';
  let slots = 1;
  for (const value of root) {
    if (slots-- <= 0) return 'Every value after the root needs a parent in the level-order array.';
    if (value === null) continue;
    if (!Number.isInteger(value) || value < -100 || value > 100) return 'Node values are whole numbers from -100 to 100.';
    slots += 2;
  }
  return null;
}

