function adapt(input, solve, kit) {
  const [values] = input;
  class Node {
    constructor(val) { this.val = val; this.left = null; this.right = null; this.next = null; }
  }
  // Build the tree depth by depth; levels[d] lists the nodes at depth d from left to right.
  const root = values.length > 0 ? new Node(values[0]) : null;
  const levels = root ? [[root]] : [];
  let next = 1;
  for (let depth = 0; depth < levels.length; depth++) {
    const below = [];
    for (const node of levels[depth]) {
      for (const side of ['left', 'right']) {
        if (next < values.length && values[next] !== null) {
          node[side] = new Node(values[next]);
          below.push(node[side]);
        }
        next++;
      }
    }
    if (below.length > 0) levels.push(below);
  }
  const nodes = levels.flat();
  const links = nodes.map(node => [node.val, node.left, node.right]);
  const result = solve(root);
  if (result === undefined) throw new Error('The solution did not return a value.');
  if (result !== root) throw new Error('Return the root of the input tree.');
  const intact = nodes.every((node, i) => node.val === links[i][0] && node.left === links[i][1] && node.right === links[i][2]);
  if (!intact) throw new Error('The tree must keep its values and child links.');
  // Serialize as LeetCode does: follow next from each depth's leftmost node, then mark the end with #.
  const out = [];
  for (const level of levels) {
    let count = 0;
    for (let node = level[0]; node; node = node.next) {
      if (++count > nodes.length) throw new Error('The next pointers form a loop.');
      out.push(node.val);
    }
    out.push('#');
  }
  return out;
}

