function connect(root) {
  let levelStart = root;
  while (levelStart !== null) {
    const dummy = new Node(0);
    let tail = dummy;
    for (let node = levelStart; node !== null; node = node.next) {
      if (node.left !== null) {
        tail.next = node.left;
        tail = tail.next;
      }
      if (node.right !== null) {
        tail.next = node.right;
        tail = tail.next;
      }
    }
    levelStart = dummy.next;
  }
  return root;
}

