function connect(root) {
  // A preorder walk (left before right) meets each depth's nodes from left to right,
  // so each node is linked from the previous node seen at the same depth.
  const lastAtDepth = [];
  const visit = (node, depth) => {
    if (!node) return;
    if (lastAtDepth[depth]) lastAtDepth[depth].next = node;
    lastAtDepth[depth] = node;
    visit(node.left, depth + 1);
    visit(node.right, depth + 1);
  };
  visit(root, 0);
  return root;
}

