function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const n = size === 'large' ? 800 + pick(150) : pick(12);
  if (n === 0) return [[]];
  const span = size === 'large' || rand() < 0.5 ? 100 : 5;
  const value = () => pick(2 * span + 1) - span;
  // style 0 fills slots in level order (complete tree), 1 grows deep and thin, 2 attaches anywhere.
  const style = pick(3);
  const root = { val: value(), left: null, right: null };
  const free = [[root, 'left'], [root, 'right']];
  for (let count = 1; count < n; count++) {
    const at = style === 0 ? 0 : style === 1 ? free.length - 1 - pick(2) : pick(free.length);
    const [parent, side] = free.splice(at, 1)[0];
    const child = { val: value(), left: null, right: null };
    parent[side] = child;
    free.push([child, 'left'], [child, 'right']);
  }
  const out = [];
  const queue = [root];
  for (let q = 0; q < queue.length; q++) {
    const node = queue[q];
    out.push(node ? node.val : null);
    if (node) queue.push(node.left, node.right);
  }
  while (out[out.length - 1] === null) out.pop();
  return [out];
}
